import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

/**
 * TASK: Give TemperatureLog custom writeObject / readObject methods.
 *
 * The readings array and the average are transient, so default serialization
 * throws them away. Fix that by hand:
 *   writeObject must call out.defaultWriteObject(), then write readings.length
 *   with writeInt, then every reading with writeInt.
 *   readObject must call in.defaultReadObject(), read the length, fill a new
 *   int[] of that size with readInt, store it, and set average to mean(...).
 * Whatever writeObject writes, readObject must read back in the same order.
 *
 * Example: a log of {10, 20, 30} survives a round trip with readings
 * {10, 20, 30} and average 20.0; a log with no readings has average 0.0.
 */
public class TemperatureLog implements Serializable {
    private static final long serialVersionUID = 1L;

    private String stationId;
    private transient int[] readings;
    private transient double average;

    public TemperatureLog(String stationId, int[] readings) {
        this.stationId = stationId;
        this.readings = readings.clone();
        this.average = mean(this.readings);
    }

    public String getStationId() {
        return stationId;
    }

    public int[] getReadings() {
        return readings == null ? null : readings.clone();
    }

    public double getAverage() {
        return average;
    }

    static double mean(int[] values) {
        if (values == null || values.length == 0) {
            return 0.0;
        }
        long sum = 0;
        for (int value : values) {
            sum += value;
        }
        return (double) sum / values.length;
    }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();
        // TODO: write the length of readings, then each reading
    }

    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        // TODO: read the length, rebuild the readings array, recompute average
    }
}

