import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class TemperatureLogTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(int[] values) {
        return values == null ? "null" : java.util.Arrays.toString(values);
    }

    static double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }

    static TemperatureLog roundTrip(TemperatureLog log) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
                out.writeObject(log);
            }
            try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
                return (TemperatureLog) in.readObject();
            }
        } catch (Exception e) {
            System.out.println("FAIL  round trip threw " + e.getClass().getSimpleName());
            failures++;
            return null;
        }
    }

    public static void main(String[] args) {
        TemperatureLog copy = roundTrip(new TemperatureLog("NORTH", new int[] {10, 20, 30}));
        check("station id survives", "NORTH", copy == null ? null : copy.getStationId());
        check("readings survive", "[10, 20, 30]", copy == null ? "null" : show(copy.getReadings()));
        check("average recomputed", 20.0, copy == null ? -1.0 : round2(copy.getAverage()));

        TemperatureLog uneven = roundTrip(new TemperatureLog("EAST", new int[] {10, 20, 31}));
        check("uneven average rounded", 20.33, uneven == null ? -1.0 : round2(uneven.getAverage()));

        TemperatureLog single = roundTrip(new TemperatureLog("WEST", new int[] {7}));
        check("single reading", "[7]", single == null ? "null" : show(single.getReadings()));
        check("single average", 7.0, single == null ? -1.0 : round2(single.getAverage()));

        TemperatureLog empty = roundTrip(new TemperatureLog("SOUTH", new int[0]));
        check("empty readings", "[]", empty == null ? "null" : show(empty.getReadings()));

        TemperatureLog negative = roundTrip(new TemperatureLog("PEAK", new int[] {-5, 5, -10, 10}));
        check("negative readings", "[-5, 5, -10, 10]", negative == null ? "null" : show(negative.getReadings()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

